var i=[{title:`Qué tan compleja es un ejercicio`,text:`Un remo en máquina con apoyo se mueve por una trayectoria estable. Un peso muerto rumano a una pierna pide equilibrio, control del tronco y coordinación de la cadera, y un swing con kettlebell añade velocidad y sincronización. Puedes ser muy fuerte y seguir siendo nuevo en una de estas habilidades.`},{title:`De lo predecible a lo desafiante`,text:`Empieza con posiciones estables y repeticiones más lentas, y aprende una habilidad nueva cada vez. Después haz el ejercicio más difícil quitando apoyo, cambiando la palanca, aumentando el rango o añadiendo velocidad controlada. Una progresión debería mantener el propósito del movimiento y evitar cambiar todas las exigencias a la vez.`},{title:`La fatiga cambia la coordinación`,text:`Un ejercicio que hiciste bien al principio de una sesión puede volverse inestable tras muchas repeticiones. Haz antes los ejercicios de mucha habilidad, descansa más cuando lo necesites y termina una serie cuando se te escape el equilibrio o el control. Los ejercicios balísticos complejos suelen ser una mala primera opción para quien empieza y está cansado.`},{title:`Ejemplo`,text:`Si estás aprendiendo las zancadas, podrías empezar con sentadillas divididas sujetándote a una barandilla, pasar a zancadas hacia atrás sin apoyo y probar las zancadas caminando más adelante. Una variante más rápida no es automáticamente mejor.`},{title:`Cómo usar TrainUp`,text:`Cuando TrainUp crea tu plan, elige ejercicios que encajan con tu nivel y tu coordinación, además de con tus limitaciones y tu equipamiento.`}];var n=[{label:`Declaración de posición del ACSM de 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Guía práctica del ACSM de 2026`,url:`https://www.acsm.org/wp-content/uploads/2026/03/Resistance-Training-Position-Stand-infographic.pdf`}];var o={sections:i,sources:n};export{o as default,i as sections,n as sources};